<dialog x-ref="lightbox" class="inline-gallery-lightbox" aria-label="نمایش آلبوم تصاویر" @click="if($event.target===$el)closeGallery()" @cancel.prevent="closeGallery()" @keydown.arrow-left.prevent="moveGallery(1)" @keydown.arrow-right.prevent="moveGallery(-1)"><div class="inline-gallery-lightbox-inner"><div class="inline-gallery-dialog-heading"><div><strong x-text="galleryTitle||'آلبوم تصاویر'"></strong><span x-text="formatNumber(galleryIndex+1)+' از '+formatNumber(galleryImages.length)"></span></div><div><a :href="galleryImages[galleryIndex]?.src||null" target="_blank" rel="noopener noreferrer" aria-label="باز کردن عکس اصلی"><x-icon name="external-link" size="20" /></a><button type="button" aria-label="بستن نمایشگر تصاویر" @click="closeGallery()"><x-icon name="x" size="23" /></button></div></div><div class="inline-gallery-lightbox-stage"><img x-show="!galleryFailed" :src="galleryImages[galleryIndex]?.src||null" :alt="galleryImages[galleryIndex]?.alt||''" x-on:error="galleryFailed=true" @load="galleryFailed=false"><p x-show="galleryFailed" role="alert" x-cloak>نمایش این عکس انجام نشد. <a :href="galleryImages[galleryIndex]?.src||null" target="_blank" rel="noopener noreferrer">باز کردن عکس اصلی</a></p><button type="button" class="inline-gallery-previous" aria-label="عکس قبلی" x-show="galleryImages.length>1" @click="moveGallery(-1)"><x-icon name="chevron-right" size="27" /></button><button type="button" class="inline-gallery-next" aria-label="عکس بعدی" x-show="galleryImages.length>1" @click="moveGallery(1)"><x-icon name="chevron-left" size="27" /></button></div><p class="inline-gallery-image-caption" aria-live="polite" x-text="galleryImages[galleryIndex]?.alt||('تصویر '+formatNumber(galleryIndex+1))"></p><div class="inline-gallery-thumbnails" x-show="galleryImages.length>1" aria-label="انتخاب عکس"><template x-for="(image,index) in galleryImages" :key="index"><button type="button" :aria-label="'نمایش عکس '+formatNumber(index+1)" :aria-pressed="index===galleryIndex" @click="galleryIndex=index;galleryFailed=false"><img :src="image.src" alt="" loading="lazy"></button></template></div></div></dialog>
<dialog x-ref="albumViewer" class="gallery-dialog" aria-label="{{ P::t('نمایشگر تصاویر') }}" @click="if($event.target===$el)closeGallery()" @cancel.prevent="closeGallery()" @keydown.arrow-left.prevent="moveGallery({{ P::locale()==='en'?-1:1 }})" @keydown.arrow-right.prevent="moveGallery({{ P::locale()==='en'?1:-1 }})"><div class="viewer-header"><span x-text="formatNumber(galleryIndex+1)+' / '+formatNumber(galleryImages.length)"></span><div><button type="button" :aria-label="galleryZoom?'کوچک‌نمایی':'بزرگ‌نمایی'" @click="galleryZoom=!galleryZoom"><span x-show="galleryZoom"><x-icon name="zoom-out" /></span><span x-show="!galleryZoom"><x-icon name="zoom-in" /></span></button><a :href="galleryImages[galleryIndex]?.src||null" target="_blank" rel="noopener noreferrer" aria-label="{{ P::t('باز کردن فایل اصلی') }}"><x-icon name="download" /></a><button type="button" aria-label="{{ P::t('بستن نمایشگر') }}" @click="closeGallery()"><x-icon name="x" /></button></div></div><div class="viewer-stage"><button type="button" aria-label="{{ P::t('رسانه قبلی') }}" @click="moveGallery(-1)"><x-icon :name="P::locale()==='en'?'arrow-left':'arrow-right'" /></button><div class="viewer-media" :class="galleryZoom?'zoomed':''"><img :src="galleryImages[galleryIndex]?.src||null" :alt="galleryImages[galleryIndex]?.alt||'تصویر آلبوم'"></div><button type="button" aria-label="{{ P::t('رسانه بعدی') }}" @click="moveGallery(1)"><x-icon :name="P::locale()==='en'?'arrow-right':'arrow-left'" /></button></div><p class="viewer-caption" x-text="galleryImages[galleryIndex]?.alt||''"></p><div class="viewer-thumbnails"><template x-for="(image,index) in galleryImages" :key="index"><button type="button" :aria-current="index===galleryIndex?'true':null" :aria-label="'رسانه '+formatNumber(index+1)" @click="galleryIndex=index;galleryZoom=false"><img :src="image.src" alt="" loading="lazy"></button></template></div></dialog>
